import React from "react";
import type { Status, StatusItem } from "../../types";
import "./StatusList.css";

export const STATUS_LABELS: Record<Status, string> = {
  todo: "To Do",
  "in-progress": "In Progress",
  done: "Done",
  blocked: "Blocked",
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  switch (status) {
    case "todo":
      return "status-dot--todo";
    case "in-progress":
      return "status-dot--in-progress";
    case "done":
      return "status-dot--done";
    case "blocked":
      return "status-dot--blocked";
  }
}

const STATUS_ORDER: Status[] = ["todo", "in-progress", "blocked", "done"];

interface StatusListProps {
  items: StatusItem[] | null;
}

export function StatusList({ items }: StatusListProps): React.ReactElement {
  if (items === null) {
    return (
      <ul className="status-list" aria-label="Status list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="skeleton-item">
            <div className="skeleton-line skeleton-line--short" />
          </li>
        ))}
      </ul>
    );
  }

  const grouped = STATUS_ORDER.reduce<Record<Status, StatusItem[]>>(
    (acc, status) => {
      acc[status] = items.filter((item) => item.status === status);
      return acc;
    },
    { todo: [], "in-progress": [], done: [], blocked: [] }
  );

  const activeStatuses = STATUS_ORDER.filter(
    (status) => grouped[status].length > 0
  );

  return (
    <ul className="status-list" aria-label="Status list">
      {activeStatuses.map((status) => (
        <li key={status} className="status-group">
          <div className="status-group-heading">
            <span className={`status-dot ${statusColor(status)}`} />
            <span>{STATUS_LABELS[status]}</span>
          </div>
          <ul className="status-items">
            {grouped[status].map((item) => (
              <li key={item.id} className="status-item">
                {item.label}
              </li>
            ))}
          </ul>
        </li>
      ))}
    </ul>
  );
}

