    border: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-default);
    border-radius: var(--shelf-radius-full);
    font-family: var(--shelf-font-family-base);
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-medium);
    cursor: pointer;
    transition: color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter),
                border-color var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter);
  }

  .chip-filter-btn:hover {
    color: var(--shelf-fgColor-default);
    border-color: var(--shelf-fgColor-muted);
  }

  .chip-filter-btn:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }

  .chip-filter-btn[aria-pressed="true"] {
    color: var(--shelf-fgColor-accent);
    border-color: var(--shelf-fgColor-accent);
    font-weight: var(--shelf-font-weight-semibold);
  }
}
`;

export function ChipFilter(): JSX.Element {
  const [active, setActive] = useState<ChipLabel>('All');

  return (
    <>
      <style>{CHIP_CSS}</style>
      <div role="group" aria-label="Filter chips" className="chip-bar">
        {CHIPS.map((chip) => (
          <button
            key={chip}
            type="button"
            className="chip-filter-btn"
            aria-pressed={active === chip}
            onClick={() => setActive(chip)}
          >
            {chip}
          </button>
        ))}
      </div>
    </>
  );
}

