import React, { useEffect, useState } from "react";
import { getTasks } from "../../api";
import type { Task } from "../../types";
import "./TaskBoard.css";

const SKELETON_COUNT = 4;

export function TaskBoard(): React.ReactElement {
  // null = loading; array (possibly empty) = loaded
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then(setTasks)
      .catch(() => setTasks([]));
  }, []);

  const isLoading = tasks === null;
  const isEmpty = tasks !== null && tasks.length === 0;
  const isPopulated = tasks !== null && tasks.length > 0;

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h1 className="task-board-title">Tasks</h1>
        {!isLoading && (
          <span className="task-board-badge" aria-label={`${tasks.length} tasks`}>
            {tasks.length}
          </span>
        )}
      </header>

      <div className="task-board-filter-bar" />

      {isLoading && (
        <ul className="task-list" aria-label="Tasks">
          {Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <li key={i} className="skeleton-task">
              <div className="skeleton-line skeleton-line--medium" />
            </li>
          ))}
        </ul>
      )}

      {isEmpty && (
        <p className="task-board-empty">No tasks yet.</p>
      )}

      {isPopulated && (
        <ul className="task-list" aria-label="Tasks">
          {tasks.map((task) => (
            <li key={task.id} className="task-item">
              {task.title}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

