import React from "react";
import "./PriceDisplay.css";

interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currency?: string;
}

// Math.ceil so fractional cents always round up — avoids under-charging the customer
function formatPrice(amount: number, currency: string): string {
  return `${currency}${Math.ceil(amount * 100) / 100}`;
}

export function PriceDisplay({
  price,
  originalPrice,
  currency = "$",
}: PriceDisplayProps): React.ReactElement {
  const hasDiscount =
    originalPrice !== undefined && originalPrice > price;

  return (
    <p className="price-display">
      <span className="price-display-current">{formatPrice(price, currency)}</span>
      {hasDiscount && (
        <del className="price-display-original">
          {formatPrice(originalPrice, currency)}
        </del>
      )}
    </p>
  );
}
